  /* =========================================================
   4. 构建与运行时逻辑
   ========================================================= */
  const MKEYS = ["power", "prosperity", "margin", "cr5", "elasticity"];
  function build(key, raw) {
    const idx = { u: 0, m: 0, d: 0 };
    const nodes = raw.ns.map((a) => {
      const id = a[0] + idx[a[0]]++;
      const m = {};
      MKEYS.forEach((k, i) => (m[k] = a[3][i]));
      return {
        id,
        l: a[0],
        icon: a[1],
        name: a[2],
        m,
        co: a[4],
        s: a[5],
        desc: a[6],
      };
    });
    const layers = raw.ly.map((x, i) => ({
      id: ["u", "m", "d"][i],
      name: x[0],
      note: x[1],
    }));
    return {
      key,
      name: raw.name,
      grp: raw.grp,
      scale: raw.scale,
      cycle: raw.cycle,
      updated: raw.up,
      layers,
      nodes,
      links: raw.lk,
    };
  }
  const CHAINS = {};
  Object.entries(RAW).forEach(([k, r]) => (CHAINS[k] = build(k, r)));

