  function firmSubs(co) {
    if (SUBS[co.name])
      return SUBS[co.name].map(([n, t, p, s, r]) => ({
        name: n,
        type: t,
        place: p,
        stake: s,
        rev: r,
        fake: false,
      }));
    const tpl = SUBTPL[co.l] || SUBTPL.m,
      h = hash(co.id + "@s"),
      n = 3 + (r01(h) > 0.6 ? 1 : 0);
    let left = 88;
    const out = [];
    for (let i = 0; i < n; i++) {
      const t = tpl[(h + i * 7) % tpl.length];
      if (i === n - 1) {
        if (left > 0)
          out.push({
            name: `${co.name} · ${t[0]}`,
            type: t[0],
            place: SUBCITY[(h + i * 5) % SUBCITY.length],
            stake: [100, 100, 80, 65, 51][(h + i * 3) % 5],
            rev: left,
            fake: true,
          });
        break;
      }
      const rv = Math.round(left * (0.34 + r01(h + i) * 0.28));
      left -= rv;
      out.push({
        name: `${co.name} · ${t[0]}`,
        type: t[0],
        place: SUBCITY[(h + i * 5) % SUBCITY.length],
        stake: [100, 100, 80, 65, 51][(h + i * 3) % 5],
        rev: rv,
        fake: true,
      });
    }
    return out.sort((a, b) => b.rev - a.rev);
  }

