  /* 企业 → 申万三级行业 */
  function sw3Of(co, c) {
    const sw2 = swOf(co, c),
      fix = SW_CO3[co.name];
    if (fix && SW_L3P[fix] === sw2) return fix; // 三级须与二级归属一致
    const node = (co.nodeName || "") + " " + (co.name || "");
    for (const [re, l3] of NODE_SW3) {
      if (re.test(node) && SW_L3P[l3] === sw2) return l3;
    }
    const m = CHAIN_SW3[c.key],
      l3 = m && m[co.l];
    if (l3 && SW_L3P[l3] === sw2) return l3;
    return SW_L3_DEF[sw2] || "综合Ⅲ";
  }
  /* ---- 行业分类体系 ---- */
  const TAXO = {
    sw: { n: "申万行业", lv: [1, 2, 3] },
    citic: { n: "中信行业", lv: [1, 2] },
    csic: { n: "证监会行业（国标门类 / 大类）", lv: [1, 2] },
    theme: { n: "赛道 / 概念板块", lv: [1] },
  };
  const LVLN = { 1: "一级", 2: "二级", 3: "三级" };
  let swSys = "sw",
    swLvl = 2;
  /* 企业 → 指定体系指定层级的行业（主题体系可多归属） */
  function catOf(co, c, sys, lvl) {
    sys = sys || swSys;
    lvl = lvl || swLvl;
    const sw2 = swOf(co, c);
    if (sys === "sw") {
      if (lvl === 1) return [swL1(sw2)];
      if (lvl === 2) return [sw2];
      return [sw3Of(co, c)];
    }
    if (sys === "citic") {
      const l2 = SW2_CITIC[sw2] || "综合";
      return lvl === 1 ? [CITIC_L1[l2] || "综合"] : [l2];
    }
    if (sys === "csic") {
      const g = SW2_GB[sw2] || "其他制造业";
      return lvl === 1 ? [GB_A[g] || "制造业"] : [g];
    }
    const out = [];
    THEMES.forEach((t) => {
      let hit = false;
      if (t.ch && t.ch.indexOf(c.key) >= 0) hit = true;
      else if (
        t.kw &&
        t.kw.some((k) =>
          new RegExp(k).test(
            (co.name || "") + "|" + (co.nodeName || "") + "|" + (c.name || ""),
          ),
        )
      )
        hit = true;
      else if (t.f && t.f(co, c)) hit = true;
      if (hit) out.push(t.n);
    });
    return out.length ? [...new Set(out)] : ["其他"];
  }
  const catOf1 = (x) => catOf(x.co, x.c);
  /* 体系 + 层级下的全部行业名（含上级信息） */
  function catAll() {
    const seen = {};
    swAllCos().forEach((x) => {
      catOf1(x).forEach((ind) => {
        seen[ind] = (seen[ind] || 0) + (x.co.revenue || 0);
      });
    });
    return Object.keys(seen);
  }
  /* 行业 → 上级（用于左栏分组）；主题体系返回赛道分组 */
  function catParent(ind) {
    if (swSys === "sw") {
      if (swLvl === 1) return "申万";
      if (swLvl === 2) return swL1(ind);
      return SW_L3P[ind] || "其他";
    }
    if (swSys === "citic")
      return swLvl === 1 ? "中信" : CITIC_L1[ind] || "综合";
    if (swSys === "csic") return swLvl === 1 ? "门类" : GB_A[ind] || "制造业";
    const t = THEMES.find((t) => t.n === ind);
    return t ? t.g : "其他";
  }
  function catColor(ind) {
    if (swSys === "sw") {
      const l2 = swLvl === 1 ? null : swLvl === 2 ? ind : SW_L3P[ind];
      return swLvl === 1
        ? SW_L1C[ind] || "#2563eb"
        : SW_L1C[swL1(l2)] || "#2563eb";
    }
    if (swSys === "citic")
      return swLvl === 1
        ? CITIC_L1C[ind] || "#2563eb"
        : CITIC_L1C[CITIC_L1[ind]] || "#2563eb";
    if (swSys === "csic")
      return swLvl === 1
        ? GB_AC[ind] || "#2563eb"
        : GB_AC[GB_A[ind]] || "#2563eb";
    const t = THEMES.find((t) => t.n === ind);
    return t ? t.c : "#2563eb";
  }
