  function windOf(key) {
    const b = MBETA[key] || MBETA.default;
    let num = 0,
      den = 0;
    MFAC.forEach((f) => {
      const s = f.v();
      num += ((b[f.k] || 0) * (s - 50)) / 50;
      den += Math.abs(b[f.k] || 0);
    });
    return Math.round(clamp(den ? (num / den) * 100 : 0, -100, 100));
  }
  function chainTopCos(key, n) {
    const c = CHAINS[key];
    if (!c) return [];
    return getCompanies(c).slice(0, n || 3);
  }
  /* ====== 挖掘：分类索引 + 行业聚合（按指定体系 / 层级） ====== */
  let _mcIdx = null;
  const mcSysOf = (S) => (S === "theme" ? "theme" : "sw");
  const mcLvlOf = (S) => (S === "sw3" ? 3 : S === "sw2" ? 2 : 1);
  function mcIndex(S) {
    if (_mcIdx && _mcIdx.key === S && _mcIdx.map) return _mcIdx.map;
    const map = {},
      sys = mcSysOf(S),
      lvl = mcLvlOf(S);
    swAllCos().forEach((x) => {
      catOf(x.co, x.c, sys, lvl).forEach((i) => {
        (map[i] = map[i] || []).push(x);
      });
    });
    _mcIdx = { key: S, map };
    return map;
  }
  function mcStats(S) {
    mcIndex(S);
    if (_mcIdx.stats) return _mcIdx.stats;
    const sys = mcSysOf(S),
      lvl = mcLvlOf(S);
    _mcIdx.stats = Object.keys(_mcIdx.map)
      .map((ind) => swStat(ind, sys, lvl))
      .filter(Boolean)
      .sort((a, b) => b.rev - a.rev);
    return _mcIdx.stats;
  }
  function mcSysName(S) {
    return S === "theme"
      ? "赛道 / 概念"
      : S === "sw2"
      ? "申万二级行业"
      : "申万三级行业";
  }
  function mcColor(ind, S) {
    if (mcSysOf(S) === "theme") {
      const t = THEMES.find((x) => x.n === ind);
      return t ? t.c : "#64748b";
    }
    const l2 = mcLvlOf(S) === 3 ? SW_L3P[ind] || "" : ind;
    return SW_L1C[swL1(l2)] || "#64748b";
  }
  function mcGroup(ind, S) {
    if (mcSysOf(S) === "theme") {
      const t = THEMES.find((x) => x.n === ind);
      return t ? t.g : "其他";
    }
    const l2 = mcLvlOf(S) === 3 ? SW_L3P[ind] || "" : ind;
    return swL1(l2) || "其他";
  }
  function indWind(st) {
    let num = 0,
      den = 0;
    st.list.forEach((x) => {
      const w = windOf(x.c.key),
        r = x.co.revenue || 0;
      num += w * r;
      den += r;
    });
    return Math.round(den ? num / den : 0);
  }
  /* 新兴度打分（行业 / 赛道）：成长 · 创新 · 扩产 · 景气 · 格局 · 安全 */
  function emergeScore(st) {
    const cy = indCycle(st);
    const qs = st.list.map((x) => firmQuality(x.c, x.co, x.fin));
    const cd = qs.reduce((s, q) => s + q.capexDep, 0) / qs.length;
    const growth = +clamp(((st.growth + 15) / 60) * 100, 0, 100).toFixed(0);
    const innov = +clamp((st.rd / 12) * 100, 0, 100).toFixed(0);
    const expand = +clamp(((cd - 0.6) / 1.4) * 100, 0, 100).toFixed(0);
    const boom = cy.pros;
    const struct = +clamp(100 - st.cr5 * 1.05, 0, 100).toFixed(0);
    const safe = +clamp(100 - st.risk, 0, 100).toFixed(0);
    const total = +(
      growth * 0.26 +
      innov * 0.2 +
      expand * 0.16 +
      boom * 0.14 +
      struct * 0.12 +
      safe * 0.12
    ).toFixed(1);
    return {
      growth,
      innov,
      expand,
      boom,
      struct,
      safe,
      total,
      cy,
      capexDep: +cd.toFixed(2),
      grade: total >= 68 ? "S" : total >= 58 ? "A" : total >= 48 ? "B" : "C",
      tag:
        total >= 68
          ? "新型产业主线"
          : total >= 58
          ? "成长赛道"
          : total >= 48
          ? "观察培育"
          : "成熟 / 传统",
      col:
        total >= 68
          ? "#059669"
          : total >= 58
          ? "#16a34a"
          : total >= 48
          ? "#2563eb"
          : "#94a3b8",
    };
  }
  /* 新兴度打分（企业）：成长 · 创新 · 产业新兴度 · 卡位 · 扩产 · 产能 · 安全 */
  function starOf(x, ind, med, indE) {
    const co = x.co,
      q = firmQuality(x.c, co, x.fin);
    const growth = +clamp(((co.growth + 15) / 60) * 100, 0, 100).toFixed(0);
    const innov = +clamp(((co.rd || 0) / 12) * 100, 0, 100).toFixed(0);
    const fresh = +clamp(((indE - 40) / 50) * 100, 0, 100).toFixed(0);
    const lead = +clamp(
      ((co.share || 0) / Math.max(2, med.share)) * 42,
      0,
      100,
    ).toFixed(0);
    const util = +clamp((((co.capacity || 0) - 35) / 65) * 100, 0, 100).toFixed(
      0,
    );
    const expand = +clamp(((q.capexDep - 0.6) / 1.4) * 100, 0, 100).toFixed(0);
    const safe = +clamp(100 - x.risk.total, 0, 100).toFixed(0);
    const total = +(
      growth * 0.26 +
      innov * 0.2 +
      fresh * 0.18 +
      lead * 0.14 +
      expand * 0.12 +
      util * 0.06 +
      safe * 0.04
    ).toFixed(1);
    const tags = [];
    if (lead >= 65 && total >= 62) tags.push("新兴龙头");
    if (
      (co.rd || 0) >= 7 &&
      (co.revenue || 0) < 600 &&
      (co.share || 0) >= 8 &&
      (co.share || 0) <= 30
    )
      tags.push("专精特新");
    if (q.capexDep >= 1.3) tags.push("扩产先锋");
    if ((co.growth || 0) - med.growth >= 12) tags.push("弯道超车");
    if ((co.margin || 0) >= 25 && (co.growth || 0) < 12) tags.push("现金牛");
    if (x.risk.total >= 60) tags.push("高杠杆");
    return {
      x,
      co,
      ind,
      q,
      total,
      growth,
      innov,
      fresh,
      lead,
      util,
      expand,
      safe,
      tags,
      col:
        total >= 70
          ? "#059669"
          : total >= 60
          ? "#16a34a"
          : total >= 50
          ? "#2563eb"
          : total >= 40
          ? "#f59e0b"
          : "#94a3b8",
    };
  }
  function mcFirms(S) {
    mcStats(S);
    if (_mcIdx.firms) return _mcIdx.firms;
    const med = {};
    mcStats(S).forEach((st) => {
      const gs = st.list.map((x) => x.co.growth || 0).sort((a, b) => a - b),
        ss = st.list.map((x) => x.co.share || 0).sort((a, b) => a - b);
      med[st.ind] = {
        growth: gs[Math.floor(gs.length / 2)] || 0,
        share: ss[Math.floor(ss.length / 2)] || 8,
      };
    });
    const emap = {};
    mcStats(S).forEach((st) => {
      emap[st.ind] = emergeScore(st).total;
    }); // 先挖产业，再在产业内挖企业
    const all = [];
    Object.entries(_mcIdx.map).forEach(([ind, list]) => {
      list.forEach((x) =>
        all.push(
          starOf(x, ind, med[ind] || { growth: 0, share: 8 }, emap[ind] || 50),
        ),
      );
    });
    all.sort((a, b) => b.total - a.total);
    const seen = {},
      out = []; // 赛道口径下企业可多归属，仅保留得分最高的一次
    all.forEach((r) => {
      if (!seen[r.co.id]) {
        seen[r.co.id] = 1;
        out.push(r);
      }
    });
    _mcIdx.firms = out;
    return out;
  }
  /* ====== 视图状态 ====== */
  let mcMode = "dash",
    mcKey = "pmi",
    mcChain = null,
    mcInd = "",
    mcScope = "theme",
    mcQ = "";
  const mcWrap = (s, n) => {
    const out = [];
    let t = "";
    for (const ch of String(s)) {
      t += ch;
      if (t.length >= n) {
        out.push(t);
        t = "";
      }
    }
    if (t) out.push(t);
    return out;
  };
  function mcSpark(g, x, y, w, h, d, col, o) {
    o = o || {};
    const mn = Math.min(...d),
      mx = Math.max(...d),
      rg = Math.max(1e-6, mx - mn);
    const px = (i) => x + (i / (d.length - 1)) * w,
      py = (v) => y + h - ((v - mn) / rg) * h;
    const pts = d
      .map((v, i) => px(i).toFixed(1) + "," + py(v).toFixed(1))
      .join(" ");
    if (o.fill)
      g.append(
        el("polygon", {
          points: `${x},${y + h} ${pts} ${x + w},${y + h}`,
          fill: col,
          "fill-opacity": 0.12,
        }),
      );
    g.append(
      el("polyline", {
        points: pts,
        fill: "none",
        stroke: col,
        "stroke-width": o.sw || 1.5,
        "stroke-linejoin": "round",
      }),
    );
    g.append(
      el("circle", {
        cx: px(d.length - 1),
        cy: py(d[d.length - 1]),
        r: o.r || 2.6,
        fill: col,
      }),
    );
    return { px, py };
  }
